            period = int(kind[6:])
            if t < period:
                return 0.5
            return 0.85 if xs[t - period] else 0.15
        return 0.5

    priors = {
        "fair": 0.24,
        "frequency": 0.18,
        "recent": 0.14,
        "repeat": 0.09,
        "alternate": 0.12,
        "transition": 0.07,
        "copy": 0.035,
        "counter": 0.045,
        "win_stay": 0.04,
        "period3": 0.02,
